SELECT s1.`c0` AS `t`, s1.`c1` AS `nf` FROM (SELECT s2.`c7` AS `c0`, s2.`c8` AS `c1` FROM (SELECT s3.`c0` AS `c0`, s3.`c1` AS `c1`, s3.`c2` AS `c2`, s3.`c3` AS `c3`, s3.`c4` AS `c4`, s3.`c5` AS `c5`, s3.`c6` AS `c6`, (CASE WHEN s3.`c5` THEN TRUE ELSE FALSE END) AS `c7`, (CASE WHEN (NOT s3.`c5`) THEN FALSE ELSE TRUE END) AS `c8` FROM (SELECT s4.`c0` AS `c0`, s4.`c1` AS `c1`, s4.`c2` AS `c2`, s4.`c3` AS `c3`, s4.`c4` AS `c4`, s4.`c5` AS `c5`, s4.`c6` AS `c6` FROM (SELECT `d` AS `c0`, `d2` AS `c1`, `ts` AS `c2`, `x` AS `c3`, `s` AS `c4`, `ok` AS `c5`, `v` AS `c6` FROM `events`) AS s4 WHERE ((CASE WHEN (CAST(3 AS BIGINT) < s4.`c3`) THEN TRUE ELSE FALSE END) IS TRUE)) AS s3) AS s2) AS s1
